tokens = sys.stdin.read().split()
nodes = [None if t == 'null' else [int(t), None, None] for t in tokens]
root = nodes[0]
queue = [root]
pos = 1
for node in queue:
    for side in (1, 2):
        if pos < len(nodes):
            child = nodes[pos]
            pos += 1
            node[side] = child
            if child is not None:
                queue.append(child)

def leaves(node):
    if node is None:
        return []
    if node[1] is None and node[2] is None:
        return [node[0]]
    return leaves(node[1]) + leaves(node[2])

