def gen(rng):
    def serialize(vals, left, right):
        out = [str(vals[0])]
        q = [0]
        i = 0
        while i < len(q):
            u = q[i]
            i += 1
            for c in (left[u], right[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)
    def rval(vmax):
        return rng.randint(-vmax, vmax)
    def random_tree(n, vmax=10**9):
        vals = [rval(vmax)]
        left, right = [-1], [-1]
        slots = [(0, 0), (0, 1)]
        for _ in range(n - 1):
            j = rng.randrange(len(slots))
            slots[j], slots[-1] = slots[-1], slots[j]
            p, side = slots.pop()
            vals.append(rval(vmax))
            left.append(-1)
            right.append(-1)
            v = len(vals) - 1
            (left if side == 0 else right)[p] = v
            slots.append((v, 0))
            slots.append((v, 1))
        return serialize(vals, left, right)
    def caterpillar(spine, zig):
        vals, left, right = [rval(10**9)], [-1], [-1]
        cur = 0
        for i in range(spine):
            for side in (0, 1):
                vals.append(rval(10**9))
                left.append(-1)
                right.append(-1)
            a, b = len(vals) - 2, len(vals) - 1
            if zig and i % 2 == 0:
                a, b = b, a
            if rng.random() < 0.5 and not zig:
                a, b = b, a
            left[cur], right[cur] = a, b
            cur = a if i % 3 else b
            if i == spine - 1:
                break
        return serialize(vals, left, right)
    def chain_then_random(chain, n):
        vals, left, right = [rval(10**9)], [-1], [-1]
        cur = 0
        for i in range(chain - 1):
            vals.append(rval(10**9))
            left.append(-1)
            right.append(-1)
            v = len(vals) - 1
            if rng.random() < 0.5:
                left[cur] = v
            else:
                right[cur] = v
            cur = v
        slots = [(cur, 0), (cur, 1)]
        for _ in range(n - chain):
            j = rng.randrange(len(slots))
            slots[j], slots[-1] = slots[-1], slots[j]
            p, side = slots.pop()
            vals.append(rval(10**9))
            left.append(-1)
            right.append(-1)
            v = len(vals) - 1
            (left if side == 0 else right)[p] = v
            slots.append((v, 0))
            slots.append((v, 1))
        return serialize(vals, left, right)
    def complete(n):
        vals = [rval(10**9) for _ in range(n)]
        left = [2 * i + 1 if 2 * i + 1 < n else -1 for i in range(n)]
        right = [2 * i + 2 if 2 * i + 2 < n else -1 for i in range(n)]
        return serialize(vals, left, right)
