        String all = new String(System.in.readAllBytes()).trim();
        String[] tokens = all.split("\\s+");
        Long[] nodes = new Long[tokens.length];
        for (int i = 0; i < tokens.length; i++) nodes[i] = tokens[i].equals("null") ? null : Long.valueOf(tokens[i]);
        long[][] res = leafList(nodes);
